fn process_item(item)
  let a = parse(item)
  let b = transform(a)
  let c = validate(b)
  let d = format(c)
  let e = serialize(d)
  // 5 heap slots = 5 wasted nova_rc_dec(0) calls on entry
  return e

// Called 10M times in a batch pipeline

fn pick(flag, a, b)
  let result = ""
  if flag
    result = a     // slot_store: result <- a (load_origin: slot.a)
  else
    result = b     // slot_store: result <- b (load_origin: slot.b)
  return result    // load from slot.result -> load_origin = slot.result
                   // But what if result was assigned via copy from a or b?
                   // If load_origin says 'slot.result', then slot.result is excluded from dec
                   // but slots a and b are BOTH dec'd (they are params, should be excluded too)
                   // Actually params are excluded by the param rule. 
                   // Real issue: result holds same object as a or b (rc_inc at slot_store)
                   // But without Stage C, no rc_inc -> dec on result at cleanup frees the param's value

fn transform(data)
  let copy = data       // slot_store: no inc (Stage C not active)
  let result = process(copy)
  return result
  // Function exit: dec slot.copy (data's RC drops to 0 -> freed)
  // dec slot.data -> SKIPPED (param, not reassigned)
  // But caller still holds 'data' which is now freed
  // Actually: 'data' is a param -> excluded from dec
  // 'copy' holds same pointer as 'data' -> dec on 'copy' frees it
  // Caller's slot for 'data' is now dangling

let x = [1,2,3]
let y = transform(x)
print(x)  // USE-AFTER-FREE: x was freed by transform's cleanup of 'copy'

fn build_response(items)
  let result = {}
  for item in items
    let key = item.name        // index_get -> may be stored -> rc_inc (find_tag)
    let val = transform(item)  // rc_dec old val (find_tag), rc_inc new val (find_tag) on overwrite
    result[key] = val
  return result
  // Function exit: rc_dec for every slot: result, key, val, item, items
  // Each rc_dec calls nova_rc_is_managed -> nova_mem_find_tag
  // For 1000 items: ~4000 find_tag calls at ~30-50ns each = 120-200us
  // Design estimates: 0.5-1.0us total. Actual: 100-200x higher.

