    i = i + 1
  // 10M atomic RC ops at ~20ns each = 200ms overhead vs 30ms non-atomic

fn handle_request(req)
  let ctx = {"request": req}
  let handler = fn() { ctx["response"] = "ok" }  // closure captures ctx
  ctx["handler"] = handler  // dict holds closure that holds dict -> CYCLE
  handler()
  return ctx["response"]
  // ctx RC=2 (slot + closure capture), handler RC=2 (slot + dict value)
  // Function exit: dec ctx -> RC=1, dec handler -> RC=1. Neither freed. LEAK.

